import os
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional, Union

import boto3


def retrieve_recent_logs(
    log_group_name: str,
    field_filters: Optional[Dict[str, Union[str, int, float, bool]]] = None,
    start_time: Optional[datetime] = None,
    end_time: Optional[datetime] = None,
    limit: int = 100,
    region_name: Optional[str] = None,
    log_stream_names: Optional[List[str]] = None,
) -> List[Dict[str, Any]]:
    client = boto3.client("logs", region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION"))

    now = datetime.now(timezone.utc)
    if end_time is None:
        end_time = now
    if start_time is None:
        start_time = end_time - timedelta(hours=1)

    if start_time.tzinfo is None:
        start_time = start_time.replace(tzinfo=timezone.utc)
    if end_time.tzinfo is None:
        end_time = end_time.replace(tzinfo=timezone.utc)

    start_ms = int(start_time.timestamp() * 1000)
    end_ms = int(end_time.timestamp() * 1000)

    filter_pattern = ""
    if field_filters:
        parts = []
        for key, value in field_filters.items():
            if isinstance(value, bool):
                rendered = "true" if value else "false"
            elif isinstance(value, (int, float)):
                rendered = str(value)
            else:
                escaped = str(value).replace('"', '\\"')
                rendered = f'"{escaped}"'
            parts.append(f"$.{key} = {rendered}")
        filter_pattern = "{ " + " && ".join(parts) + " }"

    params: Dict[str, Any] = {
        "logGroupName": log_group_name,
        "startTime": start_ms,
        "endTime": end_ms,
        "limit": limit,
    }
    if filter_pattern:
        params["filterPattern"] = filter_pattern
    if log_stream_names:
        params["logStreamNames"] = log_stream_names

    events: List[Dict[str, Any]] = []
    next_token: Optional[str] = None

    while len(events) < limit:
        if next_token:
            params["nextToken"] = next_token
        response = client.filter_log_events(**params)
        for event in response.get("events", []):
            events.append(
                {
                    "event_id": event.get("eventId"),
                    "timestamp": event.get("timestamp"),
                    "ingestion_time": event.get("ingestionTime"),
                    "log_stream_name": event.get("logStreamName"),
                    "message": event.get("message"),
                }
            )
            if len(events) >= limit:
                break

        new_token = response.get("nextToken")
        if not new_token or new_token == next_token:
            break
        next_token = new_token

    return events[:limit]
